using TicketClassifier.Services;

namespace TicketClassifier;

public class ModelTrainingHostedService : IHostedService
{
    private readonly TicketModelService _modelService;

    public ModelTrainingHostedService(TicketModelService modelService)
    {
        _modelService = modelService;
    }

    public Task StartAsync(CancellationToken cancellationToken)
    {
        _modelService.TrainAndEvaluate();
        return Task.CompletedTask;
    }

    public Task StopAsync(CancellationToken cancellationToken) => Task.CompletedTask;
}

